import{_ as t,o,c as s,a4 as a}from"./chunks/framework.C83Ss68L.js";const u=JSON.parse('{"title":"ADR-0009: The @/ alias is used in src/, rewritten by tsc-alias at build","description":"Cross-folder imports use @/ instead of ../../ chains; tsc-alias rewrites them in the emitted JavaScript.","frontmatter":{"title":"ADR-0009: The @/ alias is used in src/, rewritten by tsc-alias at build","description":"Cross-folder imports use @/ instead of ../../ chains; tsc-alias rewrites them in the emitted JavaScript."},"headers":[],"relativePath":"explanation/decisions/adr-0009-alias-imports-in-src.md","filePath":"explanation/decisions/adr-0009-alias-imports-in-src.md","lastUpdated":1792333063000}'),i={name:"explanation/decisions/adr-0009-alias-imports-in-src.md"};function r(c,e,d,n,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0009-the-alias-is-used-in-src-rewritten-by-tsc-alias-at-build" tabindex="-1">ADR-0009: The <code>@/</code> alias is used in <code>src/</code>, rewritten by <code>tsc-alias</code> at build <a class="header-anchor" href="#adr-0009-the-alias-is-used-in-src-rewritten-by-tsc-alias-at-build" aria-label="Permalink to &quot;ADR-0009: The `@/` alias is used in `src/`, rewritten by `tsc-alias` at build&quot;">​</a></h1><p><strong>Status:</strong> Accepted · <strong>Date:</strong> 2026-10-18</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>src/</code> used relative imports throughout. The rule was explicit — every cross-folder import carried an explicit <code>.js</code> extension for NodeNext ESM, and <code>AGENTS.md</code> stated that &quot;<code>@/</code> is for tests and examples, not source imports&quot;.</p><p>That rule has a cost that grows with the tree. A service reached from an adapter is <code>../../core/services/access.service.js</code>; from a deeper adapter, a fourth level. Every one of those is a path a reader must count, and a refactor that moves a file breaks all of them.</p><p>The <code>@/*</code> alias was already declared in <code>tsconfig.json</code>, <code>tsconfig.examples.json</code> and Vitest&#39;s config. It mapped to <code>src/*</code>, and nothing in <code>src/</code> used it.</p><p>The counter-argument was real and was verified before deciding: <strong><code>tsc</code> does not rewrite path aliases in its output.</strong> A file importing <code>@/schemas/access.schema.js</code> compiles cleanly and emits that specifier verbatim into <code>dist/</code>, where Node cannot resolve it. The package would install successfully and fail at first import.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Cross-folder imports in <code>src/</code> use the alias, keeping the <code>.js</code> extension: <code>import { useLogger } from &quot;@/core/services/logger.service.js&quot;</code>. Same-folder imports stay relative, where <code>./x.js</code> is already the shortest correct form.</p><p><code>tsc-alias</code> is a dev dependency and runs immediately after <code>tsc6</code> in <code>bun run build</code>, which rewrites every alias to a relative path in the emitted JavaScript <strong>and</strong> in the declaration files.</p><p><code>~/*</code> and <code>~#/…</code> are declared alongside <code>@/*</code>, pointing at the same target, for readers who expect the Nuxt convention.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Better.</strong> Import depth stops mattering. <code>@/core/services/access.service.js</code> is as readable from five levels down as from one, and moving a file no longer touches every importer. <code>@/*</code> resolves to <code>src/*</code> rather than a barrel, so a new module needs no index and no export wiring to be importable.</p><p><strong>Worse.</strong> A build step that was a single <code>tsc</code> now has a second tool, and the failure mode of forgetting it is silent at build time and loud only at install time for the consumer. <code>bun run check</code> alone does <strong>not</strong> run <code>tsc-alias</code>; it typechecks only, which is correct — the rewrite belongs to emit, not to verification. Anything else that compiles <code>src/</code> independently (<code>tsconfig.examples.json</code>, an editor task, a one-off <code>tsc</code>) emits unresolved aliases and must either run <code>tsc-alias</code> after it or only be used for typechecking.</p><p><strong>Also.</strong> TypeScript 6 deprecates <code>baseUrl</code> and requires <code>paths</code> entries to be tsconfig-relative (<code>&quot;./src/*&quot;</code>). That is why the mapping is written with the leading <code>./</code> it no longer needs for <code>baseUrl</code> resolution.</p>',15)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
